code.FreezerAuthority.removeFreezer(address):
function removeFreezer(address freezer) public {
 int index = indexOf(c_freezers, freezer);
 if (index >= 0) {
 uint i = uint(index);
 while (i < c_freezers.length - 1) {
 c_freezers[i] = c_freezers[i + 1];
 }
 c_freezers.length--;
 }
 }

